local _, ns = ...
if ns.LOCALE ~= "frFR" then return end
local L = ns.L

-- Options/HelpPanes.lua: the FAQ and Support pages, beside Locales/frFR.lua.
L["FAQ_CAPTION"] = "Questions fréquentes, et où sont passées les choses."
L["FAQ_SEARCH"] = "Rechercher une question"
L["FAQ_NONE"] = "Aucune question ne correspond."
L["FAQ_NOT_BOUND"] = "non assigné"
L["FAQ_LFG_Q"] = "Où est mon bouton LFG (recherche de groupe) ?"
L["FAQ_LFG_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Cliquez sur l'œil de la minicarte, utilisez les onglets latéraux de l'onglet Qui de la fenêtre sociale, ou appuyez sur la touche de la recherche de groupe (%s). Pour retrouver le bouton, décochez \"%s\" sous \"%s\"."
L["FAQ_LEGACY_Q"] = "Où est mon bouton Héritage ?"
L["FAQ_LEGACY_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Cliquez sur son icône sur la minicarte. Pour retrouver le bouton, décochez \"%s\" sous \"%s\". N'importe quel bouton du micro-menu peut aller sur la minicarte : cochez-le sous \"%s\"."
L["FAQ_PROFESSIONS_Q"] = "Où est mon bouton des métiers ?"
L["FAQ_PROFESSIONS_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Ouvrez vos métiers depuis le grimoire, ou appuyez sur la touche des métiers (%s). Pour retrouver le bouton, décochez \"%s\" sous \"%s\"."
L["FAQ_COLLECTIONS_Q"] = "Où est mon bouton des collections ?"
L["FAQ_COLLECTIONS_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Ouvrez vos montures, mascottes, jouets et apparences depuis l'onglet \"%s\" au pied du grimoire, ou appuyez sur la touche des collections (%s). Pour retrouver le bouton, décochez \"%s\" sous \"%s\"."
L["FAQ_QUICKJOIN_Q"] = "Où est l'onglet %s ?"
L["FAQ_QUICKJOIN_A"] = "Dans la fenêtre sociale, ouvrez %s puis %s. L'onglet %s sous la liste y bascule, et l'onglet %s revient en arrière."
L["FAQ_REAGENT_Q"] = "Où est mon sac de composants ?"
L["FAQ_REAGENT_A"] = "C'est le petit sac rond entre le trousseau et votre dernier sac, affiché quand la souris survole vos sacs. Pour le garder visible, choisissez \"%s\", ou \"%s\" pour un emplacement comme les autres sacs."
L["FAQ_TENBUTTONS_Q"] = "Pourquoi ma barre principale affiche-t-elle 10 boutons, ou la mauvaise taille ?"
L["FAQ_TENBUTTONS_A"] = "Le bandeau suit les réglages de la barre d'action 1 en mode édition : \"%s\" et \"%s\". \"%s\" sur la page \"%s\" donne les boutons plus petits de la 1.x."
L["FAQ_GRYPHONS_Q"] = "Comment masquer les griffons ?"
L["FAQ_GRYPHONS_A"] = "Sur la page \"%s\", réglez \"%s\" ou \"%s\" sur \"%s\". En mode édition, chaque griffon est un élément à part, à déplacer ou masquer."
L["FAQ_XPBAR_Q"] = "Puis-je masquer la barre d'expérience ou la sortir du bandeau ?"
L["FAQ_XPBAR_A"] = "Oui, en mode édition. Cliquez sur la barre d'expérience ou de réputation : elle peut être sortie du bandeau, et sa fenêtre propose \"%s\"."
L["FAQ_SIZE_Q"] = "Pourquoi les fenêtres sont-elles plus petites que celles du jeu ? Puis-je les agrandir ?"
L["FAQ_SIZE_A"] = "Ce sont les tailles de Classic Era. Cliquez sur le cadenas dans la barre de titre d'une fenêtre et tirez la poignée de son coin, ou réglez sa taille en mode édition sous \"%s\". Les barres suivent \"%s\" et la taille dans la fenêtre de chaque barre en mode édition."
L["FAQ_SCALE_Q"] = "Pourquoi mon interface est-elle plus grande ?"
L["FAQ_SCALE_A"] = "Classic Era dessine son interface plus grande que Forever. Choisir la disposition classique avec la taille d'Era règle l'échelle de l'interface du jeu sur celle-ci, 90 %% sur la plupart des écrans. Modifiez-la à tout moment dans %s, dans les options du jeu (« %s »)."
L["FAQ_SCALEBACK_Q"] = "Comment retrouver mon ancienne taille d'interface ?"
L["FAQ_SCALEBACK_A"] = "Appuyez sur « %s » dans la barre latérale avec « %s » cochée : votre taille d'avant revient avec les options. Ou réglez-la dans %s, dans les options du jeu ; décochez « %s » pour la taille automatique du jeu."
L["FAQ_SCALEBACK_PIECE_A"] = "Réglez-la dans %s, dans les options du jeu ; décochez « %s » pour la taille automatique du jeu."
L["FAQ_GLOW_Q"] = "Comment désactiver la lueur rouge de mes cadres ?"
L["FAQ_GLOW_A"] = "Sur la page \"%s\" : \"%s\" pour la lueur rouge quand quelque chose vous attaque, \"%s\" pour la pulsation de votre cadre de joueur pendant que vous attaquez."
L["FAQ_TRACKER_Q"] = "Puis-je retrouver l'ancien suivi des quêtes ?"
L["FAQ_TRACKER_A"] = "Oui. Sur la page \"%s\", \"%s\" choisit son apparence, dont le suivi des quêtes de Classic Era."
L["FAQ_PLATES_Q"] = "Comment agrandir les barres d'infos ?"
L["FAQ_PLATES_A"] = "Leur taille est celle du jeu, sous \"%s\" dans ses Options. \"%s\" sur la page \"%s\" ne change que le nom."
L["FAQ_MOVE_Q"] = "Puis-je déplacer les fenêtres ?"
L["FAQ_MOVE_A"] = "Oui, hors combat. Survolez la barre de titre d'une fenêtre et cliquez sur son cadenas, puis faites-la glisser par le titre. Ou placez les fenêtres en mode édition sous \"%s\". Le bouton rouge à côté du cadenas remet une fenêtre à sa place par défaut."
L["FAQ_MOVERS_Q"] = "Pourquoi mon addon de déplacement de fenêtres en déplace certaines et pas d'autres ?"
L["FAQ_MOVERS_A"] = "La fiche de personnage et les autres fenêtres du jeu sont celles du jeu à l'aspect 1.x, donc ces addons peuvent les déplacer ; \"%s\" dans les options les leur laisse entièrement. Notre grimoire et notre journal de quêtes sont faits par nous, car le jeu n'en a aucun comme ceux d'Era, et ces addons ne déplacent que les fenêtres de leur propre liste. Les nôtres se déplacent avec le cadenas de leur barre de titre, ou en mode édition."
L["FAQ_SETTING_Q"] = "Puis-je changer l'apparence ou le fonctionnement de quelque chose ?"
L["FAQ_SETTING_A"] = "Très probablement. Presque chaque élément peut être désactivé ou ajusté : tapez un mot dans le champ \"%s\" en haut à gauche de cette fenêtre. Si vous ne le trouvez pas, demandez sur GitHub ou CurseForge."
L["FAQ_FOREVER_Q"] = "Puis-je garder l'apparence propre à Forever pour certaines parties ?"
L["FAQ_FOREVER_A"] = "Oui. Chaque élément classique a son propre interrupteur dans cette fenêtre ; désactivez-le et celui de Forever revient. Certains changements demandent un rechargement, et une fenêtre vous le propose."
L["FAQ_OTHER_ADDON_Q"] = "Pouvez-vous rendre %s compatible avec un autre addon ?"
L["FAQ_OTHER_ADDON_A"] = "Dites-nous lequel sur GitHub ou CurseForge et nous y jetterons un œil. Quand deux addons modifient la même partie de l'écran, désactiver cette partie ici permet en général aux deux de fonctionner."
L["FAQ_LFG_RETAIL_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Cliquez sur l'œil de la minicarte, ou appuyez sur la touche de la recherche de groupe (%s). Pour retrouver le bouton, décochez \"%s\" sous \"%s\"."
L["FAQ_REAGENT_RETAIL_A"] = "Il occupe l'ancien emplacement du trousseau, au bout de vos sacs. Pour un emplacement comme les autres sacs, choisissez \"%s\"."
L["FAQ_OWNLOOK_Q"] = "Puis-je garder l'apparence propre au jeu pour certaines parties ?"
L["FAQ_OWNLOOK_A"] = "Oui. Chaque élément classique a son propre interrupteur dans cette fenêtre ; désactivez-le et celui du jeu revient. Certains changements demandent un rechargement, et une fenêtre vous le propose."
L["FAQ_RETAILBUTTONS_Q"] = "Où sont mes boutons %s, %s et %s ?"
L["FAQ_RETAILBUTTONS_A"] = "La 1.x n'en avait pas, ils ne sont donc pas dans le micro-menu. Cliquez sur leurs icônes sur la minicarte, ou appuyez sur la touche de %s (%s) ou de %s (%s). Pour retrouver un bouton, décochez-le sous \"%s\"."
L["FAQ_SUITE_Q"] = "Qu'est-ce que ClassicUI Forever ?"
L["FAQ_SUITE_A"] = "La suite d'addons complète dont vient cette partie : tout le style de la 1.x, des barres et sacs aux cadres d'unité, cartes et fenêtres. Un seul fonctionne à la fois ; pour plus que cette partie, utilisez ClassicUI Forever complet et désactivez ce que vous ne voulez pas."
L["FAQ_SUITE_PICKER_A"] = "La suite d'addons complète pour laquelle ce sélecteur de couleur a d'abord été créé : tout le style de la 1.x, des barres et sacs aux cadres d'unité, cartes et fenêtres, avec ce sélecteur de couleur intégré. Un seul fonctionne à la fois ; pour avoir les deux, utilisez ClassicUI Forever complet."
L["FAQ_MICRO_KEY_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Appuyez sur sa touche (%s). Pour retrouver le bouton, décochez \"%s\" sous \"%s\"."
L["FAQ_MICRO_OFF_A"] = "La 1.x n'en avait pas, il n'est donc pas dans le micro-menu. Pour retrouver le bouton, décochez \"%s\" sous \"%s\"."
L["FAQ_RETAILBUTTONS_KEY_A"] = "La 1.x n'en avait pas, ils ne sont donc pas dans le micro-menu. Appuyez sur la touche de %s (%s) ou de %s (%s). Pour retrouver un bouton, décochez-le sous \"%s\"."
L["SUPPORT_CAPTION"] = "Merci d'utiliser %s."
L["SUPPORT_FEEDBACK_HEAD"] = "Retours"
L["SUPPORT_FEEDBACK"] = "Rapports de bugs, idées et tout autre retour sont toujours les bienvenus. Avant d'écrire, appuyez sur %s et collez ce qu'il vous donne dans votre rapport : vos réglages, la version du jeu et vos autres addons."
L["SUPPORT_POST"] = "Choisissez ensuite où le publier. Les boutons copient l'adresse à coller dans votre navigateur."
L["SUPPORT_MORE_HEAD"] = "Vous aimerez peut-être aussi"
L["SUPPORT_MORE"] = "EasyFind, également de notre part : une palette de commandes pour le jeu. Tapez ce que vous voulez et faites-le directement depuis les résultats : ouvrir une fenêtre ou un réglage, monter, lancer un sort ou trouver un lieu sur la carte."
L["SUPPORT_MORE_BUTTON"] = "EasyFind sur CurseForge"
L["SUPPORT_SUITE_BUTTON"] = "ClassicUI Forever sur CurseForge"
L["SUPPORT_DONATE_HEAD"] = "Soutenir l'addon"
L["SUPPORT_DONATE"] = "%s est gratuit. Si vous souhaitez le soutenir, vous pouvez le faire via Buy Me a Coffee."
L["SUPPORT_DONATE_BUTTON"] = "Buy Me a Coffee"

-- Era's interface size (Options/EraScale.lua).
L["ERASCALE_OFFER"] = "Classic Era affiche son interface plus grande que Forever par défaut. Passer à la taille d'Era, avec les barres à la taille classique ? L'interface se recharge. Le réglage %s du jeu change la taille à tout moment."
L["ERASCALE_GIVEN_BACK"] = "Taille de l'interface rétablie. Elle n'a pas l'air comme prévu ? Cliquez %s."
L["ERASCALE_HELP"] = "La taille de l'interface est revenue à celle d'avant la disposition classique, ou à la taille automatique du jeu. Si elle paraît encore trop grande ou trop petite, réglez-la dans %s, dans les options du jeu : décochez « %s » pour la taille automatique, ou déplacez son curseur."
L["ERASCALE_OPEN_SETTINGS"] = "Options du jeu"
L["ERASCALE_SWITCH"] = "Taille d'Era"
L["ERASCALE_ASK"] = "Sur cet écran, votre interface n'a pas la taille de celle de Classic Era. Passer à la taille d'Era, avec les barres à la taille classique ? Le réglage %s du jeu la change à tout moment."
L["ERASCALE_KEEP"] = "Garder ma taille"
